@block DoubleCartLabPolicy begin
    # Learned controller of the double cart (plan/RL_PLAN.md, step 0): an rsl_rl PPO actor [64, 64] tanh, a single
    # network running alone, trained on the exported plant FMU (pendulum-double-cart-plant). Task: swing-up from hanging rest and balance.
    # Warm start: behaviour cloning on the example's TVLQR swing-up + balance LQR, then PPO with a BC anchor.
    # Generated by rl/make_policy_block.py from imiL/model_best.pt: do not edit by hand.
    # Every tick (Ts = 0.005 s) it reads the encoders, builds the training env's observation
    #   o = [sin th1, cos th1, sin th2, cos th2, x, (x - xp)/Ts, (th1 - th1p)/Ts, (th2 - th2p)/Ts, ap]
    # with th1 = q1 - pi/2, th2 = th1 + q2 (absolute angles from upright) and the previous samples, normalises it with
    # the stored mean and std, runs the MLP and outputs u = v_max * clamp(a, -1, 1). Before t_on: u = 0.
    @constants begin
        n0::Int = 9
        n1::Int = 64
        n2::Int = 64
    end
